import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Activity, ArrowUpRight, BookOpen, BriefcaseBusiness, Check, CheckCircle2, ChevronDown, CircleAlert, Clock3, Compass, FileText, FileUp, GraduationCap, Layers3, LoaderCircle, LockKeyhole, Moon, Play, Radar, RefreshCw, ShieldCheck, Sparkles, Sun, Target, Upload, X } from 'lucide-react';
