 async function start(){setError('');setBusy(true);setRun(null);try{const selectedJd=jdMode==='paste'?jd:'';const selectedUrl=jdMode==='url'?url:'';const selectedRole=jdMode==='role'?role:'';let res:Response;if(file){const form=new FormData();form.append('profile_file',file);form.append('jd_text',selectedJd);form.append('jd_url',selectedUrl);form.append('jd_role',selectedRole);form.append('company',company);form.append('student_id','student');form.append('weeks',String(weeks));form.append('hours_per_week',String(hours));res=await fetch(`${API}/runs/upload`,{method:'POST',body:form})}else{res=await fetch(`${API}/runs`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_text:profile,jd_text:selectedJd,jd_url:selectedUrl||null,jd_role:selectedRole||null,company:company||null,weeks,hours_per_week:hours,student_id:'student'})})}const data=await res.json();if(!res.ok)throw new Error(data.detail||'Could not start your analysis');setAnalysisProfileLabel(file?file.name:'Pasted resume or academic record');setAnalysisTargetLabel(selectedRole?(roleOptions.find(item=>item.role===selectedRole)?.title||selectedRole):selectedUrl?'Public job posting':'Pasted job description');setRun(data)}catch(e){setError(e instanceof Error?e.message:'Something went wrong')}finally{setBusy(false)}}
 async function approve(decision:'approve'|'edit'|'reject'){if(!run?.run_id)return;setBusy(true);try{const res=await fetch(`${API}/runs/${run.run_id}/approve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,note,weeks,hours_per_week:hours})});const data=await res.json();if(!res.ok)throw new Error(data.detail);const r=await fetch(`${API}/runs/${run.run_id}`);setRun(await r.json());if(data.report)setEditing(false)}catch(e){setError(e instanceof Error?e.message:'Approval failed')}finally{setBusy(false)}}
